// app/knowledge-base/page.tsx

import { KnowledgeSidebar } from './knowledge-sidebar';
import { ChatInterface } from './chat-interface';
import { fetchKbArticles } from '@/lib/api/kb';
import { generateSummary } from '@/lib/api/ai';

// Server Component — runs entirely on the server
export default async function KnowledgeBasePage({
    searchParams,
}: {
    searchParams: Promise<{ q?: string }>;
}) {
    const { q = '' } = await searchParams;

    // Fetch KB articles server-side (parallel with search)
    const articles = await fetchKbArticles(q);

    // Pre-generate AI summary for the page (server-side)
    const summary = articles.length > 0
        ? await generateSummary(articles.map(a => a.title))
        : null;

    return (
        <div className="kb-layout">
            <aside>
                <KnowledgeSidebar articles={articles} />
            </aside>
            <main>
                {summary && (
                    <section className="ai-summary">
                        <h2>AI-Generated Summary</h2>
                        <p>{summary}</p>
                    </section>
                )}
                <ChatInterface articles={articles} />
            </main>
        </div>
    );
}

// Client Component — interactive chat
'use client';
export function ChatInterface({ articles }: { articles: Article[] }) {
    const [messages, setMessages] = useState<Message[]>([]);
    const [input, setInput] = useState('');

    // Only the chat interaction logic ships to the client
    // The heavy data fetching was done in the Server Component
    return (
        <div className="chat-interface">
            {messages.map(msg => (
                <MessageItem key={msg.id} message={msg} />
            ))}
            <form onSubmit={(e) => handleSubmit(e, articles, setMessages, input)}>
                <input value={input} onChange={e => setInput(e.target.value)} />
            </form>
        </div>
    );
}

// app/knowledge-base/summary.tsx

import { Suspense } from 'react';
import { generateSummary } from '@/lib/api/ai';

export async function AISummary({ titles }: { titles: string[] }) {
    const summary = await generateSummary(titles);
    return (
        <article className="prose max-w-2xl">
            <h2>AI Summary</h2>
            <p>{summary}</p>
        </article>
    );
}

// In the parent page:
export default async function Page() {
    const articles = await fetchKbArticles();

    return (
        <main>
            {/* Articles render immediately */}
            <ArticleList articles={articles} />

            {/* Summary streams when ready */}
            <Suspense fallback={<div className="skeleton">Generating AI summary...</div>}>
                <AISummary titles={articles.map(a => a.title)} />
            </Suspense>
        </main>
    );
}
